        getComposedClassNames,
        config?.base,
        getVariantClassNames,
        getCompoundVariantClassNames,
        props?.class,
        props?.className,
      );
    };

    component.config = {
      ...config,
      variants: mergedVariants,
      defaultVariants: mergedDefaultVariants,
    };

