  }) as CVA;

  const compose: Compose = (...components) => {
    const config = components.reduce(
      (acc, { config }) => {
        Object.entries(config || {}).forEach(([key, value]) => {
          acc[key] =
            typeof value === "object" && value !== null && !Array.isArray(value)
              ? {
                  ...acc[key],
                  ...value,
                }
